/** 照片拍摄时间 */
export function photoDate(p: PhotoItem): Date {
  return new Date(p.date + 'T12:00:00')
}

/** 按时间倒序（最新在前） */
export const SORTED_PHOTOS = [...PHOTOS].sort((a, b) => b.date.localeCompare(a.date))
